void reset_display_bootstrap_test()
{
    display_bootstrap_version_result = TRUE;
    display_bootstrap_platform = VER_PLATFORM_WIN32_WINDOWS;
    display_bootstrap_module_result = reinterpret_cast<HMODULE>(0x402);
    display_bootstrap_procedure_result = reinterpret_cast<FARPROC>(display_bootstrap_create_direct_draw);
    display_bootstrap_create_result = 0;
    display_bootstrap_created_display = reinterpret_cast<void *>(0x403);
    display_bootstrap_enumerate_result = 0;
    display_bootstrap_free_count = 0;
    display_bootstrap_cooperative_count = 0;
    display_bootstrap_descriptor = {};
    gag::set_display_bootstrap_state_for_testing(0, nullptr, nullptr, 0, nullptr);
}

void test_display_bootstrap()
{
    gag::DisplayBootstrapApi bootstrap_api{ display_bootstrap_get_version, display_bootstrap_load_library, display_bootstrap_get_proc_address, display_bootstrap_get_heap, display_bootstrap_allocate,
        display_bootstrap_free, display_bootstrap_set_cooperative, display_bootstrap_enumerate };
    gag::set_display_bootstrap_api_for_testing(bootstrap_api);

    reset_display_bootstrap_test();
    display_bootstrap_version_result = FALSE;
    require(gag::initialize_direct_draw_runtime() == 0x10000 && gag::get_display_bootstrap_error_for_testing() == 0x10000);
    reset_display_bootstrap_test();
    display_bootstrap_platform = VER_PLATFORM_WIN32_NT + 2;
    require(gag::initialize_direct_draw_runtime() == 1);
    reset_display_bootstrap_test();
    display_bootstrap_module_result = nullptr;
    require(gag::initialize_direct_draw_runtime() == 1);
    reset_display_bootstrap_test();
    display_bootstrap_procedure_result = nullptr;
    require(gag::initialize_direct_draw_runtime() == 0x100000);
    reset_display_bootstrap_test();
    display_bootstrap_create_result = -1;
    require(gag::initialize_direct_draw_runtime() == 0x200000);
    reset_display_bootstrap_test();
    require(gag::initialize_direct_draw_runtime() == 0);

    reset_display_bootstrap_test();
    require(gag::enumerate_direct_draw_display_modes() == 0x200000 && display_bootstrap_cooperative_count == 0);
    gag::set_display_bootstrap_state_for_testing(1, nullptr, nullptr, 0, display_bootstrap_created_display);
    display_bootstrap_descriptor.flags = 0x1006;
    display_bootstrap_descriptor.width = 640;
    display_bootstrap_descriptor.height = 480;
    display_bootstrap_descriptor.caps = 0x55;
    display_bootstrap_descriptor.pixel_format.flags = 0x41;
    display_bootstrap_descriptor.pixel_format.bits_per_pixel = 16;
    display_bootstrap_descriptor.pixel_format.red_mask = 0xf800;
    display_bootstrap_descriptor.pixel_format.green_mask = 0x7e0;
    display_bootstrap_descriptor.pixel_format.blue_mask = 0x1f;
    display_bootstrap_descriptor.pixel_format.alpha_mask = 0x80000000;
    require(gag::enumerate_direct_draw_display_modes() == 0);
    require(display_bootstrap_cooperative_count == 2 && display_bootstrap_cooperative_modes[0] == 0x1000 && display_bootstrap_cooperative_modes[1] == 0);
    gag::DisplayMode *mode = gag::begin_display_mode_enumeration(0x20000);
    require(mode != nullptr && mode->width == 640 && mode->height == 480 && mode->surface_caps == 0x55);
    require(mode->bits_per_pixel == 16 && mode->pixel_value_count == 0x10000 && mode->green_mask == 0x7e0 && mode->alpha_mask == 0x80000000);
    require(gag::get_display_mode_count_for_testing() == 1);

    gag::LegacyDirectDrawSurfaceDescriptor duplicate = display_bootstrap_descriptor;
    duplicate.pixel_format.flags = 0x40;
    require(gag::collect_direct_draw_display_mode(&duplicate, nullptr) == 1);
    require(gag::get_display_mode_count_for_testing() == 1 && display_bootstrap_free_count == 1 && mode->pixel_format_flags == 0x40);

    gag::LegacyDirectDrawSurfaceDescriptor unsupported = display_bootstrap_descriptor;
    unsupported.width = 800;
    unsupported.pixel_format.green_mask = 0x123;
    require(gag::collect_direct_draw_display_mode(&unsupported, nullptr) == 1);
    require(gag::get_display_mode_count_for_testing() == 1 && display_bootstrap_free_count == 2);

    gag::LegacyDirectDrawSurfaceDescriptor ignored{};
    require(gag::collect_direct_draw_display_mode(&ignored, nullptr) == 1 && display_bootstrap_free_count == 2);
}

