void test_display_host_initialization()
{
    gag::DisplayHostInitializationApi host_api{ display_host_initialize_critical, display_host_delete_critical, display_host_enumerate_windows, display_host_initialize_direct_draw,
        display_host_enumerate_direct_draw, display_host_find_current };
    gag::set_display_host_initialization_api_for_testing(host_api);

    reset_display_host_test(0x80000000);
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0x123400) == 0 && bootstrap_host_initialize_count == 0);

    reset_display_host_test(0x10);
    display_host_windows_result = 7;
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0x123400) == 7);
    require(gag::get_display_host_window_for_testing() == reinterpret_cast<HWND>(0x501));
    require(bootstrap_host_initialize_count == 1 && bootstrap_host_delete_count == 1);

    reset_display_host_test();
    display_host_windows_result = 9;
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0x123400) == 9);
    require(gag::get_display_host_window_for_testing() == reinterpret_cast<HWND>(0x502));
    require(display_host_direct_initialize_count == 0 && bootstrap_host_delete_count == 1);

    reset_display_host_test();
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0x300000) == 0);
    require(display_host_direct_initialize_count == 0 && display_host_direct_enumerate_count == 0 && display_host_find_count == 1);
    require((gag::get_display_palette_flags_for_testing() & 0x80000002) == 0x80000002);

    for(std::uint32_t fallback : { 1U, 0x100000U })
    {
        reset_display_host_test();
        display_host_direct_initialize_result = fallback;
        require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0) == 0);
        require(display_host_direct_enumerate_count == 0 && display_host_find_count == 1 && bootstrap_host_delete_count == 0);
        require((gag::get_display_palette_flags_for_testing() & 0x80000002) == 0x80000002);
    }

    reset_display_host_test();
    display_host_direct_initialize_result = 0x200000;
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0) == 0x200000);
    require(bootstrap_host_delete_count == 1 && display_host_find_count == 0);

    reset_display_host_test();
    display_host_direct_enumerate_result = 0x200000;
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0) == 0x200000);
    require(display_host_direct_enumerate_count == 1 && bootstrap_host_delete_count == 1);

    reset_display_host_test();
    require(gag::initialize_display_mode_host(reinterpret_cast<HWND>(0x502), 0) == 0);
    require(display_host_direct_enumerate_count == 1 && display_host_find_count == 1 && bootstrap_host_delete_count == 0);
    require((gag::get_display_palette_flags_for_testing() & 0x80000001) == 0x80000001);
}

