void test_runtime_tree_basic_commands()
{
    gag::RuntimeTreeBasicCommandApi api{ parse_test_basic_command_value, extract_test_basic_command_text, parse_test_basic_command_scope, load_test_basic_command_resource,
        dispatch_test_basic_command_section, create_test_basic_command_node };
    gag::set_runtime_tree_basic_command_api_for_testing(api);
    gag::ScriptRuntimeRoot root{};
    gag::RuntimeTreeNode owner{};
    gag::RuntimeGenericResourceNode current_resource{};
    gag::RuntimeGenericResourceNode loaded_resource{};
    gag::RuntimeTreeNode other_result{};
    gag::set_script_runtime_root_for_testing(&root);
    gag::RuntimeNamedNodeMemoryApi memory_api{ allocate_display_scene_memory, free_display_scene_memory };
    gag::set_runtime_named_node_memory_api_for_testing(memory_api);
    root.heap = reinterpret_cast<HANDLE>(72);
    root.set_property = destroy_test_runtime_generic_resource;
    gag::RuntimeGenericResourceNode remove_first{};
    gag::RuntimeGenericResourceNode remove_second{};
    remove_first.identity = &remove_first;
    remove_first.next = &remove_second;
    remove_second.identity = &remove_second;
    root.generic_resources = &remove_first;
    runtime_generic_resource_destroy_count = 0;
    display_scene_free_count = 0;
    gag::remove_all_runtime_generic_resources();
    require(root.generic_resources == nullptr && runtime_generic_resource_destroy_count == 2 && display_scene_free_count == 2);
    gag::remove_all_runtime_generic_resources();
    gag::set_script_runtime_root_for_testing(nullptr);
    gag::remove_all_runtime_generic_resources();
    gag::set_script_runtime_root_for_testing(&root);
    gag::ScriptParserState parser{};
    parser.owner = &owner;
    parser.resource = &current_resource;

    basic_command_value_count = 0;
    basic_command_value_index = 0;
    owner.flags = 0x201;
    require(gag::dispatch_runtime_tree_section_command(&parser) == 0 && owner.flags == 1);
    basic_command_values[0] = "LOCAL";
    basic_command_value_count = 1;
    basic_command_value_index = 0;
    basic_command_result = &other_result;
    const std::uint32_t local_dispatch_result = gag::dispatch_runtime_tree_section_command(&parser);
    require(local_dispatch_result == static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(&other_result)));
    require(basic_command_resource_argument == &current_resource && basic_command_owner_argument == &owner && std::strcmp(basic_command_name_argument, "LOCAL") == 0
            && std::strcmp(basic_command_creation_argument, "ARGS") == 0);
    basic_command_values[0] = "REMOTE";
    basic_command_values[1] = "SECTION";
    basic_command_value_count = 2;
    basic_command_value_index = 0;
    basic_command_loaded_resource = nullptr;
    require(gag::dispatch_runtime_tree_section_command(&parser) == 0);
    basic_command_value_index = 0;
    basic_command_loaded_resource = &loaded_resource;
    basic_command_result = &owner;
    require(gag::dispatch_runtime_tree_section_command(&parser) == 0 && basic_command_resource_argument == &loaded_resource && std::strcmp(basic_command_name_argument, "SECTION") == 0);

    basic_command_values[0] = "EN";
    basic_command_value_count = 1;
    basic_command_value_index = 0;
    require(gag::parse_runtime_language(&parser) && std::strcmp(root.language, "EN") == 0);
    basic_command_value_count = 0;
    basic_command_value_index = 0;
    require(!gag::parse_runtime_language(&parser));

    basic_command_values[0] = "LOCAL_TREE";
    basic_command_value_count = 1;
    basic_command_value_index = 0;
    basic_command_scopes[0] = 0xffffffff;
    basic_command_scope_index = 0;
    basic_command_result = &other_result;
    require(gag::create_runtime_tree_command(&parser) == &other_result && basic_command_resource_argument == &current_resource && basic_command_parent_argument == nullptr
            && std::strcmp(basic_command_name_argument, "LOCAL_TREE") == 0 && basic_command_owner_argument == nullptr);
    basic_command_values[0] = "REMOTE";
    basic_command_values[1] = "TREE";
    basic_command_value_count = 2;
    basic_command_value_index = 0;
    basic_command_scopes[0] = 0x00200000;
    basic_command_scopes[1] = 0xffffffff;
    basic_command_scope_index = 0;
    basic_command_loaded_resource = &loaded_resource;
    owner.parent = nullptr;
    require(gag::create_runtime_tree_command(&parser) == &other_result && basic_command_resource_argument == &loaded_resource && basic_command_parent_argument == reinterpret_cast<void *>(0xffffffff)
            && std::strcmp(basic_command_name_argument, "TREE") == 0);
    basic_command_value_index = 0;
    basic_command_scope_index = 0;
    owner.parent = reinterpret_cast<gag::RuntimeTreeNode *>(0xffffffff);
    require(gag::create_runtime_tree_command(&parser) == nullptr);
    basic_command_value_count = 0;
    basic_command_value_index = 0;
    require(gag::create_runtime_tree_command(&parser) == nullptr);
}

void test_script_object_serialization()
{
    char text[2048]{};
    gag::ScriptTextBuffer buffer{ 0, sizeof(text), text };
    gag::set_script_runtime_root_for_testing(nullptr);
    gag::serialize_script_object_states(&buffer);
    require(buffer.length == 0);

    gag::ScriptRuntimeRoot root{};
    gag::set_script_runtime_root_for_testing(&root);
    root.heap = GetProcessHeap();
    root.palette_flags = 0x20;
    root.command_definition_count = 1;
    std::memcpy(root.command_definitions[0].name, "CMD", 4);
    gag::set_script_object_memory_api_for_testing({ HeapAlloc });
    gag::ScriptParserState object_parser = make_script_parser("PARSED NUM:: 7 ENABLED:: ON /COMM: CMD /MOUSE: MOUSE /AMOUSE: ALT /F: NOPAL /INVERT_NOPAL");
    require(gag::parse_script_object_state(&object_parser) == 2);
    gag::ScriptObjectState *parsed_object = root.objects;
    require(parsed_object != nullptr && std::strcmp(parsed_object->name, "PARSED") == 0 && parsed_object->integer_values[0] == 7);
    require((parsed_object->active_field_mask & 3) == 3 && parsed_object->command_mask == 1 && std::strcmp(parsed_object->mouse_visual_name, "MOUSE") == 0
            && std::strcmp(parsed_object->alternate_mouse_visual_name, "ALT") == 0 && parsed_object->image_flags == 0x20);
    HeapFree(root.heap, 0, parsed_object);
    root.objects = nullptr;

    char dispatch_text[]{ "object=DISPATCH VALUE:: 5;" };
    gag::RuntimeGenericResourceNode dispatch_resource{};
    dispatch_resource.resource_data = dispatch_text;
    dispatch_resource.resource_metadata = reinterpret_cast<void *>(sizeof(dispatch_text) - 1);
    gag::RuntimeTreeNode dispatch_owner{};
    gag::RuntimeTreeParserContext dispatch_context{};
    dispatch_context.owner = &dispatch_owner;
    dispatch_context.resource = &dispatch_resource;
    dispatch_context.resource_data = dispatch_resource.resource_data;
    dispatch_context.resource_metadata = dispatch_resource.resource_metadata;
    require(gag::dispatch_runtime_tree_parser(&dispatch_context) == &dispatch_owner);
    require(root.objects != nullptr && std::strcmp(root.objects->name, "DISPATCH") == 0 && root.objects->field_count == 1 && root.objects->integer_values[0] == 5);
    HeapFree(root.heap, 0, root.objects);
    root.objects = nullptr;
    root.palette_flags = 0;
    root.command_definition_count = 0;
    gag::serialize_script_object_states(&buffer);
    require(buffer.length == 0);

    gag::ScriptObjectState first{};
    gag::ScriptObjectState second{};
    strcpy_s(first.name, "OBJ");
    strcpy_s(first.field_names[0], "A");
    strcpy_s(first.field_names[1], "B");
    first.field_count = 2;
    first.integer_values[0] = 7;
    strcpy_s(first.string_values[1], "TXT");
    first.active_field_mask = 1;
    first.flags_042c = 0x10000;
    strcpy_s(first.mouse_visual_name, "MOUSE");
    strcpy_s(first.alternate_mouse_visual_name, "ALT");
    first.command_mask = 1;
    first.next = &second;
    strcpy_s(second.name, "EMPTY");
    root.objects = &first;
    root.command_definition_count = 2;
    strcpy_s(root.command_definitions[0].name, "CMD");
    strcpy_s(root.command_definitions[1].name, "SKIP");
    gag::serialize_script_object_states(&buffer);
    text[buffer.length] = '\0';
    require(std::strcmp(text, "\r\nobject=OBJ A:7 A:ON B:TXT B:OFF /MOUSE:MOUSE /AMOUSE:ALT /F:NATURALMOUSE /COMM:CMD;\r\nobject=EMPTY;\r\n") == 0);
}

