void test_archive_read_speed()
{
    gag::set_archive_read_speed_api_for_testing({ initialize_test_archive_speed, extract_test_archive_speed_prefix, create_test_archive_speed_host, open_test_archive_speed_record,
        get_test_archive_speed_size, read_test_archive_speed_record, get_test_archive_speed_time, close_test_archive_speed_record, destroy_test_archive_speed_host });
    archive_speed_prefix = true;
    archive_speed_host_available = true;
    archive_speed_record_available = true;
    archive_speed_size = 0x28000;
    archive_speed_times[0] = 100;
    archive_speed_times[1] = 200;
    archive_speed_time_index = 0;
    archive_speed_read_count = 0;
    require(gag::measure_archive_read_speed("D:\\Gag01.cdf", 0x18000) == 0x18000 / 100);
    const std::uint32_t limited_reads[] = { 0x8000, 0x8000, 0x8000, 0x8000 };
    require(archive_speed_read_count == 4 && std::memcmp(archive_speed_reads, limited_reads, sizeof(limited_reads)) == 0 && std::strcmp(archive_speed_root, "D:\\") == 0);

    archive_speed_prefix = false;
    archive_speed_size = 0x10000;
    archive_speed_times[0] = 10;
    archive_speed_times[1] = 20;
    archive_speed_time_index = 0;
    archive_speed_read_count = 0;
    require(gag::measure_archive_read_speed("D:\\Gag01.cdf", 0x18000) == 0x8000 / 10);
    require(archive_speed_root == nullptr && archive_speed_read_count == 2 && archive_speed_reads[0] == 0x8000 && archive_speed_reads[1] == 0x8000);

    archive_speed_times[0] = 20;
    archive_speed_times[1] = 20;
    archive_speed_time_index = 0;
    require(gag::measure_archive_read_speed("D:\\Gag01.cdf", 0) == 0);
    archive_speed_host_available = false;
    require(gag::measure_archive_read_speed("D:\\Gag01.cdf", 1) == 0);
    archive_speed_host_available = true;
    archive_speed_record_available = false;
    require(gag::measure_archive_read_speed("D:\\Gag01.cdf", 1) == 0);
}

std::uint32_t command_target_flags[4];
std::uint32_t command_target_flag_count;
std::uint32_t command_target_flag_index;
const char *command_target_tokens[2];
std::uint32_t command_target_token_index;

std::uint32_t __fastcall parse_test_command_target_flag(gag::ScriptParserState *parser)
{
    parser->cursor += 10;
    return command_target_flags[command_target_flag_index++];
}

std::uint32_t __fastcall parse_test_command_target_token(gag::ScriptParserState *parser, char *value, std::uint32_t capacity)
{
    require(capacity == 0x20);
    std::memset(value, 0, capacity);
    std::memcpy(value, command_target_tokens[command_target_token_index], std::strlen(command_target_tokens[command_target_token_index]) + 1);
    ++command_target_token_index;
    ++parser->cursor;
    return 0;
}

void prepare_test_command_target(std::initializer_list<std::uint32_t> flags, std::initializer_list<const char *> tokens)
{
    command_target_flag_count = static_cast<std::uint32_t>(flags.size());
    command_target_flag_index = 0;
    std::copy(flags.begin(), flags.end(), command_target_flags);
    command_target_token_index = 0;
    std::copy(tokens.begin(), tokens.end(), command_target_tokens);
}

void test_runtime_tree_command_target()
{
    gag::set_runtime_tree_command_target_api_for_testing({ parse_test_command_target_flag, parse_test_command_target_token });
    gag::RuntimeGenericResourceNode resource{};
    std::memcpy(resource.name, "RESOURCE", 9);
    gag::ScriptParserState parser{};
    parser.resource = &resource;
    parser.cursor = 5;
    char resource_name[0x20]{};
    char tree_name[0x20]{};
    std::uint32_t flags = 0xcccccccc;

    prepare_test_command_target({ 0xffffffff }, {});
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 0 && flags == 0 && parser.cursor == 15);
    parser.cursor = 5;
    prepare_test_command_target({ 0x20 }, {});
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 0 && flags == 0x20 && parser.cursor == 15);

    parser.cursor = 5;
    prepare_test_command_target({ 0, 0xffffffff }, { "TARGET" });
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 1 && flags == 0 && parser.cursor == 16);
    require(std::strcmp(resource_name, "RESOURCE") == 0 && std::strcmp(tree_name, "TARGET") == 0);

    parser.cursor = 5;
    prepare_test_command_target({ 0, 0x400 }, { "TARGET" });
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 1 && flags == 0x400 && parser.cursor == 16);
    require(std::strcmp(resource_name, "RESOURCE") == 0 && std::strcmp(tree_name, "TARGET") == 0);

    parser.cursor = 5;
    prepare_test_command_target({ 0, 0, 0x20 }, { "RESOURCE2", "TREE2" });
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 1 && flags == 0x20 && parser.cursor == 17);
    require(std::strcmp(resource_name, "RESOURCE2") == 0 && std::strcmp(tree_name, "TREE2") == 0);

    parser.cursor = 5;
    prepare_test_command_target({ 0, 0, 0xffffffff }, { "RESOURCE3", "TREE3" });
    require(gag::parse_runtime_tree_command_target(&parser, resource_name, tree_name, &flags) == 1 && flags == 0 && parser.cursor == 17);
}

