void test_archive_comment_enumeration()
{
    gag::set_archive_comment_enumeration_api_for_testing(
        { find_first_archive_comment, find_next_archive_comment, find_close_archive_comment, GetProcessHeap, allocate_archive_comment, reallocate_archive_comment, free_archive_comment,
            open_archive_comment, get_archive_comment_error, get_archive_comment_size, read_archive_comment, close_archive_comment, send_archive_comment, delete_archive_comment_file });
    gag::ArchiveCommentDialogState state{};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);

    reset_archive_comment_test();
    archive_comment_file_count = 0;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 2 && state.archive_paths == nullptr && archive_comment_find_close_count == 0);

    reset_archive_comment_test();
    archive_comment_files[0] = "pack2.cdf";
    archive_comment_texts[0] = "Second";
    archive_comment_file_count = 1;
    archive_comment_alloc_fails = true;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 0x10000 && archive_comment_find_close_count == 1);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_files[0] = "pack2.cdf";
    archive_comment_files[1] = "pack12.cdf";
    archive_comment_texts[0] = "Second";
    archive_comment_texts[1] = "Twelfth";
    archive_comment_file_count = 2;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 0);
    require(state.comment_count == 2 && state.comment_capacity == 10 && state.maximum_identifier == 13 && archive_comment_close_count == 2 && archive_comment_find_close_count == 1);
    require(std::strcmp(state.archive_paths, "D:\\pack2.cdf") == 0 && std::strcmp(state.archive_paths + 0x104, "D:\\pack12.cdf") == 0);
    require(archive_comment_message_count == 2 && std::strcmp(archive_comment_messages[0], "Second") == 0 && std::strcmp(archive_comment_messages[1], "Twelfth") == 0);
    HeapFree(GetProcessHeap(), 0, state.archive_paths);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_file_count = 1;
    archive_comment_oversized = true;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 2 && state.archive_paths == nullptr && state.comment_capacity == 0);
    require(archive_comment_free_count == 1 && archive_comment_close_count == 1);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_file_count = 1;
    archive_comment_read_fails = true;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 2 && archive_comment_close_count == 1 && archive_comment_message_count == 0);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_file_count = 1;
    archive_comment_open_fails = true;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 2 && archive_comment_delete_count == 0 && archive_comment_close_count == 0);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_open_fails = true;
    archive_comment_error = 0x10000;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 0x10000 && state.archive_paths == nullptr && state.comment_capacity == 0 && state.comment_count == 0);
    require(archive_comment_free_count == 1 && archive_comment_find_close_count == 1 && archive_comment_delete_count == 1 && std::strcmp(archive_comment_deleted_path, "D:\\pack2.cdf") == 0);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_file_count = 10;
    for(std::uint32_t index = 0; index < 10; ++index)
    {
        static char names[10][16];
        static char comments[10][16];
        std::sprintf(names[index], "pack%u.cdf", index);
        std::sprintf(comments[index], "Comment%u", index);
        archive_comment_files[index] = names[index];
        archive_comment_texts[index] = comments[index];
    }
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 0 && state.comment_count == 10 && state.comment_capacity == 20 && state.maximum_identifier == 10);
    require(archive_comment_realloc_count == 1 && archive_comment_close_count == 10);
    HeapFree(GetProcessHeap(), 0, state.archive_paths);

    reset_archive_comment_test();
    state = {};
    state.directory = "D:\\";
    std::memcpy(state.extension, ".cdf", 5);
    archive_comment_file_count = 10;
    archive_comment_realloc_fails = true;
    require(gag::enumerate_archive_comments(&state, reinterpret_cast<HWND>(4)) == 0 && state.comment_count == 10 && state.comment_capacity == 10 && state.archive_paths != nullptr);
    require(archive_comment_realloc_count == 1 && archive_comment_close_count == 10 && archive_comment_find_close_count == 1);
    HeapFree(GetProcessHeap(), 0, state.archive_paths);
}

