void test_runtime_sound_pause_resume()
{
    gag::set_runtime_sound_pause_resume_api_for_testing({ wait_sound_pause_resume, release_sound_pause_resume, reset_sound_pause_resume, unprepare_sound_pause_resume, close_wave_sound_pause_resume,
        post_sound_pause_resume, close_handle_sound_pause_resume, create_thread_sound_pause_resume, sleep_sound_pause_resume, open_sound_pause_resume });
    gag::set_runtime_sound_destroy_state_for_testing(0, nullptr, nullptr, 0);
    require(gag::pause_runtime_sound_output(1) == 0 && gag::resume_runtime_sound_output() == 0);

    gag::set_runtime_sound_destroy_state_for_testing(1, nullptr, nullptr, 0);
    gag::set_runtime_sound_create_state_for_testing(reinterpret_cast<HANDLE>(501), reinterpret_cast<HWAVEOUT>(503), nullptr, reinterpret_cast<WAVEHDR *>(504), reinterpret_cast<WAVEHDR *>(505),
        reinterpret_cast<HWND>(506), reinterpret_cast<HANDLE>(502), 507, 1, 1, 0);
    gag::set_runtime_sound_pause_resume_state_for_testing(0x12345678, 0, 1, 1, reinterpret_cast<HANDLE>(502), 507, reinterpret_cast<HWND>(506), 0);
    gag::toggle_runtime_sound_state();
    std::uint32_t toggle;
    std::uint32_t suppressed;
    std::uint32_t initialized;
    HANDLE thread;
    DWORD thread_id;
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    require(toggle == 0xedcba987);

    sound_pause_resume_event_count = 0;
    require(gag::pause_runtime_sound_output(0) == 1);
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    require(suppressed == 1 && initialized == 1 && thread == reinterpret_cast<HANDLE>(502) && sound_pause_resume_event_count == 2 && sound_pause_resume_events[0] == 1
            && sound_pause_resume_events[1] == 10);
    sound_pause_resume_event_count = 0;
    require(gag::resume_runtime_sound_output() == 1);
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    require(suppressed == 0 && initialized == 1 && sound_pause_resume_event_count == 2 && sound_pause_resume_events[0] == 1 && sound_pause_resume_events[1] == 10);

    sound_pause_resume_event_count = 0;
    require(gag::pause_runtime_sound_output(1) == 1);
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    const int expected_pause[]{ 1, 2, 3, 4, 2, 5, 7, 8, 9, 10 };
    require(initialized == 0 && thread == nullptr && thread_id == 0 && sound_pause_resume_event_count == 10 && std::memcmp(sound_pause_resume_events, expected_pause, sizeof(expected_pause)) == 0);

    gag::set_runtime_sound_pause_resume_state_for_testing(toggle, 1, 0, 0, nullptr, 0, reinterpret_cast<HWND>(506), 0);
    sound_pause_resume_created_thread = nullptr;
    sound_pause_resume_event_count = 0;
    require(gag::resume_runtime_sound_output() == 1);
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    require(suppressed == 0 && initialized == 0 && sound_pause_resume_event_count == 3 && sound_pause_resume_events[0] == 1 && sound_pause_resume_events[1] == 6 && sound_pause_resume_events[2] == 10);

    gag::set_runtime_sound_pause_resume_state_for_testing(toggle, 1, 0, 0, nullptr, 0, reinterpret_cast<HWND>(506), 0);
    sound_pause_resume_created_thread = reinterpret_cast<HANDLE>(502);
    sound_pause_resume_open_result = MMSYSERR_ERROR;
    sound_pause_resume_event_count = 0;
    require(gag::resume_runtime_sound_output() == 1);
    const int expected_open_failure[]{ 1, 6, 12, 7, 8, 9, 10 };
    require(sound_pause_resume_event_count == 7 && std::memcmp(sound_pause_resume_events, expected_open_failure, sizeof(expected_open_failure)) == 0);

    gag::set_runtime_sound_pause_resume_state_for_testing(toggle, 1, 0, 0, nullptr, 0, reinterpret_cast<HWND>(506), 0);
    sound_pause_resume_open_result = MMSYSERR_NOERROR;
    sound_pause_resume_event_count = 0;
    require(gag::resume_runtime_sound_output() == 1);
    gag::get_runtime_sound_pause_resume_state_for_testing(&toggle, &suppressed, &initialized, &thread, &thread_id);
    require(initialized == 1 && thread == reinterpret_cast<HANDLE>(502) && thread_id == 507 && sound_pause_resume_event_count == 4 && sound_pause_resume_events[3] == 10);

    gag::set_runtime_sound_pause_resume_state_for_testing(toggle, 1, 0, 0, nullptr, 0, nullptr, 1);
    sound_pause_resume_event_count = 0;
    require(gag::resume_runtime_sound_output() == 0 && sound_pause_resume_event_count == 2 && sound_pause_resume_events[0] == 1 && sound_pause_resume_events[1] == 6);
}

